En la @tbl-cruces_nr_interacciones comparo las tasas observadas y predichas para cruces de pares de variables categóricas. Dado que el modelo solo incluye efectos principales, las diferencias en estos cruces revelan interacciones que el modelo no captura y que pueden ser fuente de la sobre o sub-corrección.


::: {#tbl-cruces_nr_interacciones .cell tbl-cap='Tasa de respuesta observada vs predicha por cruces de variables'}

```{.r .cell-code  code-fold="true"}
# Defino una función auxiliar para calcular obs vs pred por cruce de dos variables
calcular_cruce = function(data, var1, var2) {
  data |>
    mutate(
      Cruce = paste0(var1, " × ", var2),
      Categoria = paste(.data[[var1]], "–", .data[[var2]])
    ) |>
    group_by(Cruce, Categoria) |>
    summarise(
      N = n(),
      Respondientes = sum(respuesta_muestra),
      Tasa_obs = mean(respuesta_muestra),
      Tasa_pred = mean(prob_respuesta),
      .groups = "drop"
    ) |>
    mutate(Diferencia = Tasa_obs - Tasa_pred)
}

# Calculo los cruces más relevantes
cruces_nr = bind_rows(
  calcular_cruce(df_no_respuesta, "Region", "sector"),
  calcular_cruce(df_no_respuesta, "Region", "ambito"),
  calcular_cruce(df_no_respuesta, "sector", "jornada_completa"),
  calcular_cruce(df_no_respuesta, "ambito", "jornada_completa") 
)

# Genero la tabla gt agrupada por cruce
cruces_nr |>
  gt(groupname_col = "Cruce") |>
  tab_header(
    title = "Tasa de respuesta: observada vs predicha por interacciones",
    subtitle = "Cruces de variables no modelados – Tercer año PEB 2025"
  ) |>
  cols_label(
    Categoria = "Categoría",
    Respondientes = "Resp.",
    Tasa_obs = "Tasa Obs.",
    Tasa_pred = "Tasa Pred.",
    Diferencia = "Dif."
  ) |>
  fmt_percent(
    columns = c(Tasa_obs, Tasa_pred, Diferencia),
    decimals = 1
  ) |>
  fmt_integer(columns = c(N, Respondientes)) |>
  tab_style(
    style = cell_text(color = "#c0392b", weight = "bold"),
    locations = cells_body(
      columns = Diferencia,
      rows = abs(Diferencia) > 0.10
    )
  ) |>
  tab_options(
    row_group.background.color = "#f4f4f4",
    table.width = pct(100)
  ) |>
  tab_footnote("Se resaltan en rojo las diferencias mayores a 10 puntos porcentuales.")
```

